export const importEntry = appSchema.table(
  "import_entry",
  {
    id: uuid("id").primaryKey(),
    parentOperationId: uuid("parent_operation_id")
      .notNull()
      .references(() => operation.id),
    ordinal: integer("ordinal").notNull(),
    name: text("name").notNull(),
    classification: text("classification").notNull(),
    expectedVersion: integer("expected_version"),
    expectedStateTag: text("expected_state_tag"),
    childOperationId: uuid("child_operation_id"),
    outcome: text("outcome"),
  },
  (t) => [
    unique("import_entry_parent_ordinal_key").on(t.parentOperationId, t.ordinal),
    unique("import_entry_parent_name_key").on(t.parentOperationId, t.name),
    check(
      "import_entry_classification_check",
      oneOf(t.classification, [
        "create",
        "update",
        "unchanged",
        "invalid",
        "duplicate",
        "conflict",
      ]),
    ),
    check(
      "import_entry_outcome_check",
      oneOf(t.outcome, [
        "created",
        "updated",
        "unchanged",
        "conflict",
        "rejected",
        "uncertain",
        "not_attempted",
      ]),
    ),
  ],
);

/** Exactly one row: `id` is always true. The grants migration inserts it. */
export const serviceControl = appSchema.table(
  "service_control",
  {
    id: boolean("id").primaryKey().default(true),
    captureMode: text("capture_mode").notNull().default("idle"),
    epoch: bigint("epoch", { mode: "bigint" })
      .notNull()
      .default(sql`0`),
    owner: text("owner"),
    pairId: uuid("pair_id"),
    updatedAt: timestamptz("updated_at").notNull().defaultNow(),
    // Run 6.7 (P-122, migration 0018): the backend incarnation this database
    // belongs to (also in the gate record and OpenBao's mykey-meta), and the
    // pair it was restored from. Changed by maintenance only (0017's guard).
    backendIncarnation: text("backend_incarnation"),
    restoredFromPair: uuid("restored_from_pair"),
  },
  (t) => [
    check("service_control_single_row_check", sql`${t.id}`),
    check(
      "service_control_capture_mode_check",
      oneOf(t.captureMode, ["idle", "draining", "capturing"]),
    ),
  ],
);

export const backupPair = appSchema.table(
  "backup_pair",
  {
    id: uuid("id").primaryKey(),
    captureStartedAt: timestamptz("capture_started_at").notNull(),
    boundary: jsonb("boundary").notNull(),
    artifactHashes: jsonb("artifact_hashes").notNull(),
    schemaRevision: text("schema_revision").notNull(),
    releaseCommit: text("release_commit").notNull(),
    keyRefs: jsonb("key_refs").notNull(),
    validationStatus: text("validation_status").notNull(),
    eligibleUntil: timestamptz("eligible_until"),
    createdAt: timestamptz("created_at").notNull().defaultNow(),
    // Run 6.5 (P-119, migration 0017): where the pair lives and what became of it.
    host: text("host"),
    objectKey: text("object_key"),
    manifestSha256: text("manifest_sha256"),
    invalidReason: text("invalid_reason"),
    verifiedAt: timestamptz("verified_at"),
    deletedAt: timestamptz("deleted_at"),
  },
  (t) => [
    check(
      "backup_pair_validation_status_check",
      oneOf(t.validationStatus, ["candidate", "eligible", "ineligible", "expired"]),
    ),
    index("backup_pair_host_status_idx").on(t.host, t.validationStatus, t.captureStartedAt),
  ],
);

/**
 * Run 6.5 (P-118, migration 0017): an action that reduced access while the
 * mode was not idle. Written only by app.capture_invalidate(); `txid` is the
 * writing transaction, which the barrier trigger lets through.
 */
export const backupInvalidation = appSchema.table(
  "backup_invalidation",
  {
    id: uuid("id").primaryKey(),
    at: timestamptz("at").notNull().defaultNow(),
    reason: text("reason").notNull(),
    txid: bigint("txid", { mode: "bigint" }).notNull(),
  },
  (t) => [
    check(
      "backup_invalidation_reason_check",
      oneOf(t.reason, ["sign_out", "session_revoke", "credential_revoke", "archive"]),
    ),
    index("backup_invalidation_at_idx").on(t.at),
    index("backup_invalidation_txid_idx").on(t.txid),
  ],
);

export const rateLimit = appSchema.table(
  "rate_limit",
  {
    scope: text("scope").notNull(),
    keyDigest: bytea("key_digest").notNull(),
    windowStart: timestamptz("window_start").notNull(),
    count: integer("count").notNull(),
  },
  (t) => [
    primaryKey({ name: "rate_limit_pkey", columns: [t.scope, t.keyDigest, t.windowStart] }),
    check("rate_limit_count_check", sql`${t.count} >= 0`),
  ],
);
